function Get-ExistingTags {
  param([string[]]$Lines, [int]$Start, [int]$End)
  $tags = New-Object System.Collections.Generic.List[string]
  for ($i = $Start; $i -lt $End; $i++) {
    if ($Lines[$i] -match '^tags:\s*\[(.*)\]\s*$') {
      $inner = $Matches[1]
      foreach ($tag in ($inner -split ',')) {
        $clean = $tag.Trim().Trim('"').Trim("'")
        if ($clean) { $tags.Add($clean) }
      }
    } elseif ($Lines[$i] -match '^tags:\s*$') {
      $j = $i + 1
      while ($j -lt $End -and $Lines[$j] -match '^\s*-\s*(.+?)\s*$') {
        $clean = $Matches[1].Trim().Trim('"').Trim("'")
        if ($clean) { $tags.Add($clean) }
        $j++
      }
    }
  }
  return $tags
}

function Format-TagsBlock {
  param([string[]]$Tags)
  $out = New-Object System.Collections.Generic.List[string]
  $out.Add('tags:')
  foreach ($tag in $Tags) { $out.Add("  - $tag") }
  return $out.ToArray()
}

$updated = 0
foreach ($rel in $tagMap.Keys) {
  $path = Join-Path $root ($rel -replace '/', [System.IO.Path]::DirectorySeparatorChar)
  if (-not (Test-Path -LiteralPath $path)) { throw "Missing file: $rel" }
  $text = [System.IO.File]::ReadAllText($path)
  $newline = if ($text.Contains("`r`n")) { "`r`n" } else { "`n" }
  $lines = $text -split "\r?\n", -1
  $desired = [string[]]$tagMap[$rel]

  if ($lines.Count -gt 0 -and $lines[0] -eq '---') {
    $end = -1
    for ($i = 1; $i -lt $lines.Count; $i++) {
      if ($lines[$i] -eq '---') { $end = $i; break }
    }
    if ($end -lt 0) { throw "Unclosed frontmatter: $rel" }

    $existing = Get-ExistingTags -Lines $lines -Start 1 -End $end
    $combined = @($existing + $desired | Where-Object { $_ } | Select-Object -Unique)
    $tagsBlock = Format-TagsBlock -Tags $combined

    $newFront = New-Object System.Collections.Generic.List[string]
    $i = 1
    while ($i -lt $end) {
      if ($lines[$i] -match '^tags:\s*\[.*\]\s*$') {
        foreach ($line in $tagsBlock) { $newFront.Add($line) }
        $i++
      } elseif ($lines[$i] -match '^tags:\s*$') {
        foreach ($line in $tagsBlock) { $newFront.Add($line) }
        $i++
        while ($i -lt $end -and $lines[$i] -match '^\s*-\s*.+?\s*$') { $i++ }
      } else {
        $newFront.Add($lines[$i])
        $i++
      }
    }
    if (-not ($newFront | Where-Object { $_ -match '^tags:' })) {
      if ($newFront.Count -gt 0 -and $newFront[$newFront.Count - 1] -ne '') { }
      foreach ($line in $tagsBlock) { $newFront.Add($line) }
    }
    $newLines = @('---') + $newFront.ToArray() + @('---') + $lines[($end + 1)..($lines.Count - 1)]
  } else {
    $tagsBlock = Format-TagsBlock -Tags $desired
    $newLines = @('---') + $tagsBlock + @('---', '') + $lines
  }

  $newText = [string]::Join($newline, $newLines)
  if ($newText -ne $text) {
    [System.IO.File]::WriteAllText($path, $newText, [System.Text.UTF8Encoding]::new($false))
    $updated++
  }
}
"Updated $updated markdown files."

