content.title:
$ErrorActionPreference='Stop'
$bad = @()
$count = 0
Get-ChildItem -Recurse -Filter *.md | Where-Object { $_.FullName -notmatch '\\.trash\\' -and $_.FullName -notmatch '\\Templates\\' } | ForEach-Object {
  $lines = Get-Content -LiteralPath $_.FullName -TotalCount 40
  if ($lines[0] -ne '---') { $bad += "No frontmatter: $($_.FullName)"; return }
  $end = -1
  for ($i=1; $i -lt $lines.Count; $i++) { if ($lines[$i] -eq '---') { $end = $i; break } }
  if ($end -lt 0) { $bad += "No close: $($_.FullName)"; return }
  $tagLine = -1
  for ($i=1; $i -lt $end; $i++) { if ($lines[$i] -eq 'tags:') { $tagLine = $i; break } }
  if ($tagLine -lt 0) { $bad += "No tags: $($_.FullName)"; return }
  $tagCount = 0
  for ($i=$tagLine+1; $i -lt $end; $i++) {
    if ($lines[$i] -match '^\s*-\s+(.+)$') {
      $tag = $Matches[1]
      $tagCount++
      if ($tag -match '\s') { $bad += "Whitespace tag: $($_.FullName) :: $tag" }
    }
  }
  if ($tagCount -eq 0) { $bad += "Empty tags: $($_.FullName)" }
  $count++
}
if ($bad.Count) { $bad } else { "Validated $count active non-template markdown files with frontmatter tags." }

